prefix=s[:position];order=s[position:];order=order.replace("'Inspect tables views and schemas',", "'Inspect tables views and schemas', 'Inspect column types defaults and constraints',",1)
s=prefix+chapters+order;s=s.replace("'guide_version': 18","'guide_version': 19");p.write_text(s,encoding='utf-8')
